<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { message, Modal } from 'ant-design-vue'
import { BarcodeOutlined, CheckCircleOutlined, DatabaseOutlined, EyeOutlined, FileDoneOutlined, FundOutlined, ImportOutlined, PlusOutlined, PrinterOutlined, QrcodeOutlined, ToolOutlined } from '@ant-design/icons-vue'
import dayjs, { type Dayjs } from 'dayjs'
import api from '@/api/client'
import PageBackButton from '@/components/PageBackButton.vue'

type AssetStatus = '在用' | '闲置' | '维修中' | '待处置'
interface Asset { id:number; asset_uuid:string; asset_code:string; name:string; category:string; department:string; owner:string; location:string; status:AssetStatus; value:number; purchase_date?:string; last_inventory_at?:string }
interface Task { id:number; name:string; scope:string; owner:string; status:string; due_date?:string; total_count:number; checked_count:number; exception_count:number }
interface AssetException { id:number; asset_id:number; asset_code:string; asset_name:string; department:string; type:string; description:string; status:string; resolution?:string }
interface InventoryRecord { id:number; task_id:number; asset_id:number; asset_code:string; asset_name:string; department:string; owner:string; ledger_location:string; result:string; actual_location?:string; remark?:string; photo_url?:string; checked_by?:string; checked_at?:string }
interface InventoryOwner { id:string; display_name:string; department:string; position:string; is_active:boolean }

const activeTab = ref('overview'); const loading = ref(false); const keyword = ref(''); const statusFilter = ref('全部')
const assets = ref<Asset[]>([]); const tasks = ref<Task[]>([]); const exceptions = ref<AssetException[]>([]); const summary = ref({ asset_count:0, total_value:0, inventory_completion:0, exception_count:0 })
const inventoryOwners = ref<InventoryOwner[]>([])
const assetDrawerOpen = ref(false); const taskDrawerOpen = ref(false); const editingId = ref<number | null>(null); const exceptionModalOpen = ref(false); const resolving = ref<AssetException | null>(null); const resolution = ref('')
const inventoryDrawerOpen = ref(false); const inventoryLoading = ref(false); const activeTask = ref<Task | null>(null); const inventoryRecords = ref<InventoryRecord[]>([])
const importDrawerOpen = ref(false); const importLoading = ref(false); const importRows = ref<any[]>([]); const selectedImportFile = ref<File | null>(null)
const qrModalOpen = ref(false); const qrLoading = ref(false); const activeQrAsset = ref<Asset | null>(null); const qrData = ref<any | null>(null)
const photoModalOpen = ref(false); const activePhotoRecord = ref<InventoryRecord | null>(null)
const assetForm = reactive({ asset_code:'', name:'', category:'办公设备', department:'', owner:'', location:'', status:'在用' as AssetStatus, value:0 })
const taskForm = reactive({ name:'', scope:'', owner:'', due_date:'', status:'草稿' })
const statuses = ['全部','在用','闲置','维修中','待处置']
const filteredAssets = computed(() => assets.value.filter(item => (!keyword.value || `${item.asset_code}${item.name}${item.department}${item.owner}`.toLowerCase().includes(keyword.value.toLowerCase())) && (statusFilter.value === '全部' || item.status === statusFilter.value)))
const statusColor:Record<string,string> = { 在用:'green', 闲置:'gold', 维修中:'orange', 待处置:'red' }
const exceptionColor:Record<string,string> = { 待核实:'red', 处理中:'orange', 已归档:'green' }
const uniqueValues = (values:string[]) => [...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))
const inventoryScopeOptions = computed(() => [
  { label:`全部资产（${assets.value.length} 件）`, value:'全部资产' },
  ...uniqueValues(assets.value.map(item=>item.department)).map(value=>({label:`按部门：${value}`,value:`部门：${value}`})),
  ...uniqueValues(assets.value.map(item=>item.category)).map(value=>({label:`按类别：${value}`,value:`类别：${value}`})),
  ...uniqueValues(assets.value.map(item=>item.location)).map(value=>({label:`按位置：${value}`,value:`位置：${value}`})),
])
const inventoryOwnerOptions = computed(() => inventoryOwners.value.filter(user=>user.is_active).map(user=>({value:user.display_name,label:`${user.display_name}｜${user.department}｜${user.position}`})))
const disablePastDate = (current:Dayjs) => current.isBefore(dayjs().startOf('day'))
const inventoryDoneCount = computed(() => inventoryRecords.value.filter(item=>item.result!=='未盘点').length)
const inventoryPendingCount = computed(() => inventoryRecords.value.filter(item=>item.result==='未盘点').length)
const inventoryAbnormalCount = computed(() => inventoryRecords.value.filter(item=>['位置不符','盘亏','损坏'].includes(item.result)).length)

async function loadData() { loading.value = true; try { const response = await api.get('/api/v1/assets/overview'); const data=response.data.data; summary.value=data.summary; assets.value=data.assets; tasks.value=data.tasks; exceptions.value=data.exceptions; inventoryOwners.value=data.inventory_owners } catch (error:any) { message.error(error.response?.data?.detail || '资产数据加载失败') } finally { loading.value=false } }
function openAsset(asset?:Asset) { editingId.value=asset?.id || null; Object.assign(assetForm, asset ? { ...asset, asset_code:asset.asset_code } : { asset_code:'', name:'', category:'办公设备', department:'', owner:'', location:'', status:'在用', value:0 }); assetDrawerOpen.value=true }
async function saveAsset() { if(![assetForm.asset_code,assetForm.name,assetForm.department,assetForm.owner,assetForm.location].every(value=>value.trim()))return message.warning('请完整填写资产必填信息'); try { if(editingId.value) await api.patch(`/api/v1/assets/${editingId.value}`, assetForm); else await api.post('/api/v1/assets', assetForm); message.success('资产已保存'); assetDrawerOpen.value=false; await loadData() } catch(error:any) { message.error(error.response?.data?.detail || '保存失败') } }
function removeAsset(id:number) { Modal.confirm({ title:'确认删除资产？', content:'删除后台账记录将无法恢复。', onOk:async()=>{ try{ await api.delete(`/api/v1/assets/${id}`); message.success('已删除'); await loadData() }catch(error:any){message.error(error.response?.data?.detail || '删除失败')} } }) }
async function saveTask() { if(![taskForm.name,taskForm.scope,taskForm.owner,taskForm.due_date].every(value=>value.trim()))return message.warning('请选择盘点范围、负责人和截止日期'); try { await api.post('/api/v1/assets/inventory-tasks', taskForm); message.success('盘点任务已创建'); taskDrawerOpen.value=false; Object.assign(taskForm,{name:'',scope:'',owner:'',due_date:'',status:'草稿'}); await loadData() } catch(error:any){message.error(error.response?.data?.detail || '创建失败')} }
async function openInventory(task:Task) { activeTask.value=task; inventoryDrawerOpen.value=true; inventoryLoading.value=true; try { if (!['已完成', '已结束'].includes(task.status)) await api.post(`/api/v1/assets/inventory-tasks/${task.id}/start`); inventoryRecords.value=(await api.get(`/api/v1/assets/inventory-tasks/${task.id}/records`)).data.data; await loadData() } catch(error:any){message.error(error.response?.data?.detail || '盘点任务加载失败')} finally{inventoryLoading.value=false} }
function reviewDifferences() { activeTab.value='exceptions' }
function openResolve(item:AssetException) { resolving.value=item; resolution.value=item.resolution || ''; exceptionModalOpen.value=true }
async function resolveException() { if(!resolving.value || !resolution.value.trim()) return message.warning('请输入处置结果'); try { await api.post(`/api/v1/assets/exceptions/${resolving.value.id}/resolve`,{resolution:resolution.value}); message.success('异常已归档'); exceptionModalOpen.value=false; await loadData() } catch(error:any){message.error(error.response?.data?.detail || '归档失败')} }
function beforeImportUpload(file:File) { selectedImportFile.value=file; return false }
async function previewImport() { if(!selectedImportFile.value)return message.warning('请选择CSV或XLSX文件'); importLoading.value=true; try { const formData=new FormData(); formData.append('file',selectedImportFile.value); const response=await api.post('/api/v1/assets/import/preview',formData,{headers:{'Content-Type':'multipart/form-data'}}); importRows.value=response.data.data.rows; message.success(`校验完成：${response.data.data.valid_count} 条可导入，${response.data.data.error_count} 条异常`) } catch(error:any){message.error(error.response?.data?.detail || '导入预览失败')} finally{importLoading.value=false} }
async function commitImport() { const rows=importRows.value.filter(row=>row.valid); if(!rows.length)return message.warning('没有可提交的资产行'); importLoading.value=true; try { const response=await api.post('/api/v1/assets/import/commit',{rows}); message.success(`已导入 ${response.data.data.created_count} 条资产`); importDrawerOpen.value=false; importRows.value=[]; selectedImportFile.value=null; await loadData() } catch(error:any){message.error(error.response?.data?.detail || '导入提交失败')} finally{importLoading.value=false} }
async function openQr(asset:Asset, printAfterLoad=false) { activeQrAsset.value=asset; qrModalOpen.value=true; qrLoading.value=true; try { qrData.value=(await api.get(`/api/v1/assets/${asset.id}/qr`)).data.data; if(printAfterLoad)setTimeout(()=>window.print(),300) } catch(error:any){message.error(error.response?.data?.detail || '二维码加载失败')} finally{qrLoading.value=false} }
function openQrByRecord(record:InventoryRecord) { const asset=assets.value.find(item=>item.id===record.asset_id); if(asset) openQr(asset); else message.warning('资产台账未加载，请刷新后重试') }
function printQrByRecord(record:InventoryRecord) { const asset=assets.value.find(item=>item.id===record.asset_id); if(asset) openQr(asset,true); else message.warning('资产台账未加载，请刷新后重试') }
async function rotateQr() { if(!activeQrAsset.value)return; qrLoading.value=true; try { qrData.value=(await api.post(`/api/v1/assets/${activeQrAsset.value.id}/qr/rotate`)).data.data; message.success('二维码已更新，旧码失效') } catch(error:any){message.error(error.response?.data?.detail || '二维码更新失败')} finally{qrLoading.value=false} }
function openPhoto(record:InventoryRecord) { activePhotoRecord.value=record; photoModalOpen.value=true }
function printQr() { window.print() }
const qrImageSrc = computed(() => {
  const image = qrData.value?.qr_image || ''
  const marker = 'data:image/svg+xml;utf8,'
  if (image.startsWith(marker)) return `${marker}${encodeURIComponent(image.slice(marker.length))}`
  return image
})
onMounted(loadData)
</script>

<template>
  <div class="page-frame business-page">
    <header class="page-heading"><div><p class="eyebrow">ASSET LIFECYCLE</p><h1>全资产管理</h1><p>真实数据库驱动的资产台账、盘点任务和异常处置工作台。</p></div><div class="heading-actions"><PageBackButton /><a-button @click="importDrawerOpen=true"><ImportOutlined /> 批量导入资产</a-button><a-button type="primary" @click="taskDrawerOpen=true"><BarcodeOutlined /> 新建盘点任务</a-button></div></header>
    <a-spin :spinning="loading">
      <section class="metric-grid"><a-card class="metric-card" :bordered="false"><DatabaseOutlined /><span>资产总值</span><strong>{{ (summary.total_value / 10000).toFixed(1) }} 万</strong></a-card><a-card class="metric-card" :bordered="false"><FileDoneOutlined /><span>台账资产</span><strong>{{ summary.asset_count }} 件</strong></a-card><a-card class="metric-card" :bordered="false"><FundOutlined /><span>盘点完成率</span><strong>{{ summary.inventory_completion }}%</strong></a-card><a-card class="metric-card" :bordered="false"><ToolOutlined /><span>异常待处理</span><strong>{{ summary.exception_count }} 条</strong></a-card></section>
      <a-tabs v-model:active-key="activeTab" class="business-tabs">
        <a-tab-pane key="overview" tab="运营总览"><section class="business-grid two-columns"><a-card class="plain-panel" :bordered="false"><div class="section-title"><div><p class="eyebrow">INVENTORY FLOW</p><h2>资产盘点工作流</h2></div></div><div class="workflow-row"><div class="flow-step"><span>1</span><strong>建立盘点任务</strong></div><div class="flow-line"/><div class="flow-step"><span>2</span><strong>扫码盘点</strong></div><div class="flow-line"/><div class="flow-step"><span>3</span><strong>差异复核</strong></div><div class="flow-line"/><div class="flow-step"><span>4</span><strong>处置归档</strong></div></div><a-table class="compact-table" size="small" :pagination="false" :data-source="tasks" :columns="[{title:'盘点任务',dataIndex:'name'},{title:'负责人',dataIndex:'owner'},{title:'进度',dataIndex:'checked_count'},{title:'异常',dataIndex:'exception_count'},{title:'截止日期',dataIndex:'due_date'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='checked_count'"><a-progress :percent="record.total_count ? Math.round(record.checked_count / record.total_count * 100) : 0" size="small"/></template><template v-if="column.dataIndex==='exception_count'"><a-tag :color="record.exception_count ? 'orange' : 'green'">{{ record.exception_count }} 条</a-tag></template></template></a-table></a-card><a-card class="plain-panel" :bordered="false"><div class="section-title"><div><p class="eyebrow">FULL ASSET VIEW</p><h2>全资产分布</h2></div><a-button size="small" @click="activeTab='exceptions'">处理异常</a-button></div><p v-for="category in ['办公设备','IT设备','生产工具','办公家具']" :key="category">{{ category }} <a-progress :percent="Math.min(100, assets.filter(item=>item.category===category).length * 25)" :show-info="false"/></p><a-alert type="warning" show-icon :message="`当前有 ${summary.exception_count} 条异常待处理`" description="进入异常处置页后，可逐条填写复核结论并归档。"/></a-card></section></a-tab-pane>
        <a-tab-pane key="ledger" tab="资产台账"><a-card class="plain-panel" :bordered="false"><div class="table-toolbar"><a-input v-model:value="keyword" allow-clear placeholder="搜索编号、名称、部门或责任人"/><a-select v-model:value="statusFilter" :options="statuses.map(value=>({label:value,value}))"/><a-button type="primary" @click="openAsset()"><PlusOutlined/> 新增资产</a-button></div><a-table :data-source="filteredAssets" :pagination="{pageSize:8}" :columns="[{title:'资产编号',dataIndex:'asset_code'},{title:'固定ID',dataIndex:'asset_uuid'},{title:'资产名称',dataIndex:'name'},{title:'类别',dataIndex:'category'},{title:'所属部门',dataIndex:'department'},{title:'责任人',dataIndex:'owner'},{title:'状态',dataIndex:'status'},{title:'操作',dataIndex:'actions'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='asset_uuid'"><a-typography-text copyable>{{ record.asset_uuid }}</a-typography-text></template><template v-if="column.dataIndex==='status'"><a-tag :color="statusColor[record.status]">{{record.status}}</a-tag></template><template v-if="column.dataIndex==='actions'"><a-space><a-button size="small" @click="openQr(record)"><QrcodeOutlined/> 二维码</a-button><a-button size="small" @click="openAsset(record)">编辑</a-button><a-button size="small" danger @click="removeAsset(record.id)">删除</a-button></a-space></template></template></a-table></a-card></a-tab-pane>
  <a-tab-pane key="inventory" tab="盘点工作台"><section class="business-grid"><a-card v-for="task in tasks" :key="task.id" class="task-card" :bordered="false"><div class="task-title"><strong>{{task.name}}</strong><a-tag :color="task.status==='已完成'?'green':task.status==='已结束'?'default':'processing'">{{task.status}}</a-tag></div><p>负责人：{{task.owner}}，截止：{{task.due_date || '未设置'}}</p><a-progress :percent="task.total_count ? Math.round(task.checked_count / task.total_count * 100) : 0"/><div class="task-actions"><a-button type="primary" @click="openInventory(task)"><BarcodeOutlined/> {{task.status==='草稿'?'启动盘点':(['已完成','已结束'].includes(task.status)?'查看记录':'进入盘点')}}</a-button><a-button @click="reviewDifferences"><ToolOutlined/> 差异复核</a-button></div></a-card><a-empty v-if="!tasks.length" description="暂无盘点任务"/></section></a-tab-pane>
        <a-tab-pane key="exceptions" tab="异常处置"><a-card class="plain-panel" :bordered="false"><a-table :data-source="exceptions" :pagination="false" :columns="[{title:'异常资产',dataIndex:'asset_name'},{title:'所属部门',dataIndex:'department'},{title:'异常类型',dataIndex:'type'},{title:'描述',dataIndex:'description'},{title:'状态',dataIndex:'status'},{title:'操作',dataIndex:'actions'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='status'"><a-tag :color="exceptionColor[record.status]">{{record.status}}</a-tag></template><template v-if="column.dataIndex==='actions'"><a-button size="small" type="primary" :disabled="record.status==='已归档'" @click="openResolve(record)"><CheckCircleOutlined/> 处置归档</a-button></template></template></a-table></a-card></a-tab-pane>
      </a-tabs>
    </a-spin>
    <a-drawer v-model:open="inventoryDrawerOpen" width="920" class="inventory-scan-drawer"><template #title><div><h2 class="inventory-drawer-title">扫码盘点监控台</h2><div class="drawer-subtitle">{{ activeTask?.name }} · {{ inventoryDoneCount }}/{{ inventoryRecords.length }} 已提交</div></div></template><template #extra><a-button aria-label="关闭盘点抽屉" @click="inventoryDrawerOpen=false">关闭</a-button></template><a-spin :spinning="inventoryLoading"><a-alert type="info" show-icon message="盘点方式：员工扫描贴在资产上的二维码，在手机端填写现场位置、使用人、盘点结果并上传照片。" description="后台只负责发起任务、打印二维码、跟踪提交和复核异常，不直接替员工点选完成。"/><section class="inventory-scan-stats"><a-card :bordered="false"><span>待扫码</span><strong>{{ inventoryPendingCount }}</strong></a-card><a-card :bordered="false"><span>已提交</span><strong>{{ inventoryDoneCount }}</strong></a-card><a-card :bordered="false"><span>异常</span><strong>{{ inventoryAbnormalCount }}</strong></a-card></section><a-table class="inventory-record-table" size="small" :pagination="{pageSize:8}" :data-source="inventoryRecords" :columns="[{title:'资产编号',dataIndex:'asset_code'},{title:'资产名称',dataIndex:'asset_name'},{title:'台账位置',dataIndex:'ledger_location'},{title:'现场位置',dataIndex:'actual_location'},{title:'盘点结果',dataIndex:'result'},{title:'照片',dataIndex:'photo_url'},{title:'操作',dataIndex:'actions'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='actual_location'"><span>{{ record.actual_location || '待员工提交' }}</span></template><template v-if="column.dataIndex==='result'"><a-tag :color="record.result==='正常'?'green':record.result==='未盘点'?'default':'orange'">{{record.result}}</a-tag></template><template v-if="column.dataIndex==='photo_url'"><a-button v-if="record.photo_url" size="small" @click="openPhoto(record)"><EyeOutlined/> 查看照片</a-button><a-tag v-else>未上传</a-tag></template><template v-if="column.dataIndex==='actions'"><a-space wrap><a-button size="small" type="primary" ghost @click="openQrByRecord(record)"><QrcodeOutlined/> 二维码</a-button><a-button size="small" @click="printQrByRecord(record)"><PrinterOutlined/> 打印码</a-button></a-space></template></template></a-table></a-spin></a-drawer>
    <a-drawer v-model:open="assetDrawerOpen" :title="editingId ? '编辑资产' : '新增资产'" width="520"><a-form layout="vertical"><a-form-item label="资产编号" required><a-input v-model:value="assetForm.asset_code" :disabled="Boolean(editingId)" aria-label="资产编号"/></a-form-item><a-form-item label="资产名称" required><a-input v-model:value="assetForm.name" aria-label="资产名称"/></a-form-item><a-form-item label="类别" required><a-input v-model:value="assetForm.category"/></a-form-item><a-form-item label="所属部门" required><a-input v-model:value="assetForm.department"/></a-form-item><a-form-item label="责任人" required><a-input v-model:value="assetForm.owner"/></a-form-item><a-form-item label="位置" required><a-input v-model:value="assetForm.location"/></a-form-item><a-form-item label="状态"><a-select v-model:value="assetForm.status" :options="statuses.slice(1).map(value=>({label:value,value}))"/></a-form-item><a-form-item label="资产价值"><a-input-number v-model:value="assetForm.value" :min="0" style="width:100%"/></a-form-item><a-button type="primary" block @click="saveAsset">保存资产</a-button></a-form></a-drawer>
    <a-drawer v-model:open="taskDrawerOpen" title="新建盘点任务" width="520"><a-form layout="vertical"><a-form-item label="任务名称" required><a-input v-model:value="taskForm.name" placeholder="例如：2026 年第三季度办公资产盘点"/></a-form-item><a-form-item label="盘点范围" required><a-select v-model:value="taskForm.scope" aria-label="盘点范围" show-search placeholder="选择全部资产、部门、类别或位置" :options="inventoryScopeOptions"/></a-form-item><a-form-item label="负责人" required><a-select v-model:value="taskForm.owner" aria-label="负责人" show-search option-filter-prop="label" placeholder="从系统员工中选择负责人" :options="inventoryOwnerOptions"/></a-form-item><a-form-item label="截止日期" required><a-date-picker v-model:value="taskForm.due_date" aria-label="截止日期" value-format="YYYY-MM-DD" format="YYYY-MM-DD" :disabled-date="disablePastDate" placeholder="选择截止日期" style="width:100%"/></a-form-item><a-alert type="info" show-icon message="创建后只会生成所选范围内的资产盘点记录" style="margin-bottom:16px"/><a-button type="primary" block @click="saveTask">创建任务</a-button></a-form></a-drawer>
    <a-modal v-model:open="exceptionModalOpen" title="异常处置归档" @ok="resolveException"><a-textarea v-model:value="resolution" :rows="5" placeholder="填写核实结果、调拨或报废决定"/></a-modal>
    <a-drawer v-model:open="importDrawerOpen" title="批量导入资产" width="760"><a-alert type="info" show-icon message="支持 CSV / XLSX" description="表头可用：资产编号、资产名称、类别、所属部门、责任人、位置、状态、资产价值。系统会预览重复和缺失字段，提交时跳过重复资产。"/><a-upload :before-upload="beforeImportUpload" :max-count="1" accept=".csv,.xlsx" style="display:block;margin:16px 0"><a-button><ImportOutlined/> 选择导入文件</a-button></a-upload><a-space style="margin-bottom:16px"><a-button type="primary" :loading="importLoading" @click="previewImport">预览校验</a-button><a-button :disabled="!importRows.some(row=>row.valid)" :loading="importLoading" @click="commitImport">提交可导入资产</a-button></a-space><a-table size="small" :pagination="{pageSize:6}" :data-source="importRows" :columns="[{title:'行号',dataIndex:'row_number'},{title:'资产编号',dataIndex:'asset_code'},{title:'资产名称',dataIndex:'name'},{title:'状态',dataIndex:'valid'},{title:'错误',dataIndex:'errors'}]" row-key="row_number"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='valid'"><a-tag :color="record.valid?'green':'red'">{{ record.valid ? '可导入' : '需修正' }}</a-tag></template><template v-if="column.dataIndex==='errors'"><span>{{ record.errors?.join('；') }}</span></template></template></a-table></a-drawer>
    <a-modal v-model:open="photoModalOpen" title="现场盘点照片" :footer="null" width="520"><div v-if="activePhotoRecord" class="inventory-photo-modal"><p><strong>{{ activePhotoRecord.asset_code }}</strong> · {{ activePhotoRecord.asset_name }}</p><img v-if="activePhotoRecord.photo_url" :src="activePhotoRecord.photo_url" alt="现场盘点照片"/></div></a-modal>
    <a-modal v-model:open="qrModalOpen" title="资产二维码" :width="460" :footer="null" class="asset-qr-modal" centered><a-spin :spinning="qrLoading"><div v-if="qrData" class="asset-qr-panel"><a-alert v-if="qrData.mobile_url_warning" type="warning" show-icon :message="qrData.mobile_url_warning"/><div class="asset-qr-image-wrap"><img :src="qrImageSrc" alt="资产二维码"/></div><div class="asset-qr-copy"><h3>{{ activeQrAsset?.asset_code }}</h3><p>固定ID：{{ qrData.asset_uuid }}</p><p>打印二维码贴在资产上。盘点时员工微信扫码，进入手机盘点页填写现场信息并上传照片。</p><p class="asset-qr-url">手机链接：<a-typography-text copyable>{{ qrData.mobile_url }}</a-typography-text></p></div><div class="asset-qr-actions"><a-button type="primary" @click="rotateQr">重新生成二维码</a-button><a-button @click="printQr"><PrinterOutlined/> 打印二维码</a-button><a-button :href="qrData.mobile_url" target="_blank">打开手机盘点链接</a-button></div></div></a-spin></a-modal>
  </div>
</template>
